from __future__ import annotations

from phoenix.toolbox.qop.scalar import Scalar


class Summand:
    """
    Summand class
    """

    def __init__(self, bases: tuple, comps: tuple, coeff=None):
        self._comps = comps
        self._bases = bases
        if coeff is None:
            coeff = Scalar.one()
        elif not isinstance(coeff, Scalar):
            coeff = Scalar(coeff)
        self._coeff = coeff

    @property
    def comps(self):
        return self._comps

    @property
    def bases(self):
        return self._bases

    @property
    def coeff(self):
        return self._coeff

    def copy(self):
        return Summand(self._bases, self._comps, self._coeff)
